import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"多租户 SaaS","description":"","frontmatter":{},"headers":[],"relativePath":"backend/multi-tenancy.md","filePath":"backend/multi-tenancy.md","lastUpdated":1794049926000}`),a={name:`backend/multi-tenancy.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="多租户-saas" tabindex="-1">多租户 SaaS <a class="header-anchor" href="#多租户-saas" aria-label="Permalink to “多租户 SaaS”">​</a></h1><p>本页说明租户的标识与上下文、租户目录、开通流程、成员、套餐与配额，适用于后端开发者与平台运维人员。</p><p>多租户是三件事的组合：框架解析租户上下文并严格过滤租户库实体；Tenancy 包管租户的业务（开通、套餐、成员、配额、所有权）；Runtime 把租户连接与分片接到 SqlSugar 上。</p><h2 id="标识与上下文" tabindex="-1">标识与上下文 <a class="header-anchor" href="#标识与上下文" aria-label="Permalink to “标识与上下文”">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>租户 ID</td><td>字符串，文法 <code>^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$</code>，创建后不可改；<code>platform</code> 是保留 ID</td></tr><tr><td>平台</td><td>不是一个租户：平台主体的令牌没有 <code>tenant</code> 声明；平台库实体不实现 <code>IMultiTenant</code>，要区分「平台的还是某租户的」用 <code>OwnerTenantId</code>（平台为 <code>platform</code>）</td></tr><tr><td>解析链</td><td>令牌 <code>tenant</code> 声明 → Baggage <code>xihan.tenant</code>（只来自内部调用：作业、消息处理、工作流）；不支持查询串与 <code>X-Tenant-Id</code> 头。HTTP、gRPC、MCP 入站丢掉调用方写的 <code>xihan.tenant</code>、<code>xihan.principal</code>：平台令牌带 <code>baggage</code> 头也还在平台一侧，进租户走 <code>auth.switch-tenant</code>。CloudEvents 入站的 <code>xihantenant</code> 能选租户，这是协议的设计，所以 <code>/events</code> 缺省关闭，打开后要 <code>runtime.cloud-events.deliver</code>，这个权限只在平台一侧，只授给平台的服务账号</td></tr><tr><td>隔离方式</td><td><code>Field</code>（缺省，共库、按 <code>tenant_id</code> 过滤）与 <code>Database</code>（独立库）</td></tr></tbody></table><p>框架仓储对实现 <code>IMultiTenant</code> 的实体做严格相等过滤，没有租户上下文时看不到任何行；<code>XiHan:MultiTenancy:RequireTenant</code> 为 <code>false</code>，平台主体可以调用平台侧操作。</p><h2 id="租户目录与业务实体" tabindex="-1">租户目录与业务实体 <a class="header-anchor" href="#租户目录与业务实体" aria-label="Permalink to “租户目录与业务实体”">​</a></h2><p>租户目录是框架 <code>MultiTenancy.Database</code> 的 <code>tenant_record</code>：租户 ID、显示名、是否启用、<code>ConnectionString</code>、<code>DatabaseProvider</code> 等属性，带有界缓存（<code>XiHan:MultiTenancy:Database</code>）。<code>SysTenant</code> 是 Tenancy 的业务实体：套餐、到期时间、席位与存储上限、管理员（所有者）、隔离方式与独立库状态。开通、启停、改名与修改连接时，两者在同一个工作单元中同步写入；目录里的连接串是密文，由 Runtime 的分片解析器解密。</p><p>租户停用（<code>tenants.suspend</code>）后，目录将其标记为禁用，带该租户声明的调用被框架拒绝（<code>MULTITENANCY_DENIED_001</code>），登录同样被拒绝。</p><p>租户有到期时间（<code>expiresAt</code>，为空即不限），它随目录属性同步：</p><ul><li>到期时间一过，登录（各种方式）、刷新令牌、切换租户与模仿登录即被拒绝（<code>IDENTITY_DENIED_019</code>），不等作业。</li><li>内建作业 <code>tenancy.tenants.expire</code> 每 5 分钟把过了到期时间、仍生效的租户标为到期（<code>Expired</code>）并停用目录，之后带该租户声明的调用也被拒绝。不吊销会话、不发通知。</li><li>续期：先改到期时间（<code>tenants.update</code>），再恢复（<code>tenants.resume</code>）；没延长就恢复，逐项失败 <code>TENANCY_CONFLICT_015</code>。</li></ul><h2 id="开通三步" tabindex="-1">开通三步 <a class="header-anchor" href="#开通三步" aria-label="Permalink to “开通三步”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tenants.create                        写 SysTenant + 登记租户目录（启用），绑定套餐（不填即缺省套餐）</span></span>
<span class="line"><span>  └─（独立库时）tenants.configure-database → tenants.initialize-database</span></span>
<span class="line"><span>tenants.initialize-admin              建租户管理员（系统参数 identity.password 打开时首次登录必须改密），成为所有者，并建租户内置角色 admin</span></span></code></pre></div><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>tenants.create</code> / <code>update</code> / <code>get</code> / <code>list</code></td><td><code>tenancy.tenants.create</code> / <code>update</code> / <code>read</code></td><td>平台侧；套餐不存在 <code>TENANCY_NOTFOUND_004</code>，已停用 <code>TENANCY_CONFLICT_016</code></td></tr><tr><td><code>tenants.delete</code></td><td><code>tenancy.tenants.delete</code></td><td>还有用户的租户不能删（<code>TENANCY_CONFLICT_003</code>）</td></tr><tr><td><code>tenants.suspend</code> / <code>resume</code></td><td><code>tenancy.tenants.suspend</code></td><td>批量启停；停用与到期的都能恢复，要没过到期时间（<code>TENANCY_CONFLICT_015</code>）</td></tr><tr><td><code>tenants.change-edition</code></td><td><code>tenancy.tenants.update</code></td><td>换套餐，进权限变更日志</td></tr><tr><td><code>tenants.configure-database</code></td><td><code>tenancy.tenants.configure-database</code></td><td>设隔离方式与独立库连接（<code>ISecretProtector</code> 加密）；独立库就绪后不能再改（<code>TENANCY_CONFLICT_013</code>）</td></tr><tr><td><code>tenants.initialize-database</code></td><td><code>tenancy.tenants.initialize-database</code></td><td>建库、只建租户库实体的表、在该库登记结构版本；幂等，失败记原因，改连接后可重试</td></tr><tr><td><code>tenants.initialize-admin</code></td><td><code>tenancy.tenants.initialize-admin</code></td><td>每个租户只能一次；独立库要先初始化数据库（<code>TENANCY_CONFLICT_014</code>）</td></tr><tr><td><code>tenants.transfer-owner</code></td><td><code>tenancy.tenants.transfer-owner</code></td><td>所有权转移给注册地用户或生效中的普通成员；新所有者进 <code>admin</code> 角色，原所有者保留已有角色</td></tr><tr><td><code>tenants.quotas</code></td><td><code>tenancy.tenants.read</code></td><td>各租户的用量与配额（平台侧）</td></tr><tr><td><code>tenants.mine</code></td><td>登录即可</td><td>我能进入的租户（控制中心、个人中心「我的租户」）</td></tr></tbody></table><p>独立库支持的库类型：<code>postgresql</code>、<code>sqlite</code>、<code>mysql</code>、<code>sqlserver</code>（表结构脚本只为 PostgreSQL 编写，见<a href="./upgrade">表结构升级</a>）。跨库写入是顺序提交，不是两阶段提交，见<a href="./database">数据库配置</a>。</p><h2 id="成员与切换" tabindex="-1">成员与切换 <a class="header-anchor" href="#成员与切换" aria-label="Permalink to “成员与切换”">​</a></h2><table tabindex="0"><thead><tr><th>成员类型</th><th>说明</th></tr></thead><tbody><tr><td>注册地用户</td><td><code>SysUser.HomeTenantId</code> 为该租户，可直接进入</td></tr><tr><td>普通成员（<code>Member</code>）</td><td>别处注册的账号加入该租户，带生效 / 到期</td></tr><tr><td>运维支持（<code>Support</code>）</td><td>只能是平台账号，平台运维进入租户排障用</td></tr></tbody></table><p><code>tenant-members.list / create / delete</code>（<code>tenancy.tenant-members.read / create / delete</code>，平台侧）。登录后用 <code>auth.switch-tenant</code> 在注册地、生效中的成员租户与平台之间切换：会话续用、令牌重签、前端整页重建。</p><h3 id="外部成员" tabindex="-1">外部成员 <a class="header-anchor" href="#外部成员" aria-label="Permalink to “外部成员”">​</a></h3><p>生效中的普通成员在这个租户里叫外部成员，算租户内的用户（运维支持成员不算）：</p><ul><li><code>users.list</code>、<code>users.get</code>、<code>users.detail</code> 带出他们，响应标 <code>isExternalMember</code>；不是本租户成员的账号查不到，也搜不到。</li><li>能配本租户的角色（<code>roles.assign</code>）、部门（<code>memberships.create</code>、部门负责人）、数据范围（<code>user-data-scopes.set</code>）与直授（<code>user-grants.*</code>、权限条件），也能作为委托人、字段安全目标与约束规则目标。切进租户后这些权限才算数，回到注册地不带过去。</li><li>账号本身只有注册地（或平台）能动：<code>users.update</code>、<code>users.reset-password</code>、<code>users.lock</code>、<code>users.disable</code>、<code>users.delete</code>、<code>users.reset-two-factor</code>、<code>users.set-login-policy</code> 在成员租户里一律按不存在回答。<code>users.detail</code> 不给账号安全一节，今日统计与当前会话只算这个租户里的。</li><li>被移出租户时（<code>tenant-members.delete</code>）解除他在这个租户的角色，再加回来不带旧角色；部门归属与直授留着，人不在这一侧就用不上。成员关系到期不解除，只是看不到、用不上。</li></ul><h3 id="运维支持成员" tabindex="-1">运维支持成员 <a class="header-anchor" href="#运维支持成员" aria-label="Permalink to “运维支持成员”">​</a></h3><p>生效中的运维支持成员不算租户内的用户，只进用户管理：</p><ul><li><code>users.list</code>、<code>users.get</code>、<code>users.detail</code> 带出他们，响应标 <code>isSupportMember</code>（注册在平台，<code>isExternalMember</code> 也为真）。别的选人入口用 <code>users.list</code> 的 <code>isSupportMember eq false</code> 筛掉他们。</li><li>账号只读，与外部成员相同，由平台维护。最近登录时间与 IP 是平台账号的全局信息，租户一侧不下发。</li><li>能配本租户的角色（<code>roles.assign</code>、<code>roles.update-member</code>），切进租户后按角色使用；权限条件与访问策略的试算认他们。到期或被移出之后切不进去，留在里面的会话续签被拒（<code>IDENTITY_DENIED_006</code>）；被移出时解除角色，再加回来不带旧角色。</li><li>不能配部门、数据范围与直授，也不能作为委托人、字段安全目标与约束规则目标。</li><li>不占席位，不进模仿候选、群发收件人、工作流受理人与聊天目录。</li></ul><h2 id="套餐与配额" tabindex="-1">套餐与配额 <a class="header-anchor" href="#套餐与配额" aria-label="Permalink to “套餐与配额”">​</a></h2><p><code>SysEdition</code> / <code>SysEditionGrant</code>：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>白名单</td><td>租户能生效的权限码（作用侧 Tenant / Both），至多 500 个；与有效权限求交（套餐门控，见<a href="./permission#套餐门控">权限管理</a>）</td></tr><tr><td>席位上限 / 存储上限（MB）</td><td>为空不限；租户自己的上限优先于套餐的</td></tr><tr><td>价格 / 计费周期 / 是否免费</td><td>展示与订阅用，免费套餐不能标价</td></tr><tr><td>缺省套餐</td><td>新租户不指定时绑定它；必须启用（<code>TENANCY_CONFLICT_017</code>），要停用先把别的启用套餐设为缺省</td></tr><tr><td>状态</td><td>启用 / 停用，启停并入 <code>editions.update</code>。停用后不能再分配给租户（开通或换套餐到它即 <code>TENANCY_CONFLICT_016</code>，下拉也不列）；已绑定的租户不受影响，白名单与配额照旧</td></tr></tbody></table><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>editions.list</code> / <code>get</code></td><td><code>tenancy.editions.read</code></td><td>平台侧</td></tr><tr><td><code>editions.create</code> / <code>update</code> / <code>delete</code></td><td><code>tenancy.editions.create</code> / <code>update</code> / <code>delete</code></td><td>还有租户绑定的不能删（<code>TENANCY_CONFLICT_007</code>）</td></tr><tr><td><code>editions.set-permissions</code></td><td><code>tenancy.editions.update</code></td><td>整体替换白名单，绑定的租户立即跟随，进权限变更日志</td></tr></tbody></table><p>种子 <code>tenancy.editions</code> 写四个套餐，只首写（编码已存在即跳过）：</p><table tabindex="0"><thead><tr><th>编码 / 名称</th><th>白名单</th><th>席位</th><th>存储</th><th>价格</th></tr></thead><tbody><tr><td><code>free</code> / Free（缺省）</td><td>租户侧全部 <code>read</code> 权限</td><td>5</td><td>1 GB</td><td>免费</td></tr><tr><td><code>basic</code> / Basic</td><td>Free + Identity、Organization、Settings、Files 的管理权限（不含模仿登录）</td><td>20</td><td>10 GB</td><td>99 / 月</td></tr><tr><td><code>pro</code> / Professional</td><td>Basic + Access 的全部权限</td><td>100</td><td>100 GB</td><td>299 / 月</td></tr><tr><td><code>enterprise</code> / Enterprise</td><td>创建时的全部租户侧权限</td><td>不限</td><td>不限</td><td>按年</td></tr></tbody></table><p>配额经 <code>Contracts</code> 的 <code>ITenantQuota</code> 约束租户一侧的建用户、上传与秒传（平台主体代租户办事不受限，已超额的只报告不阻止既有数据）；头像不计入租户存储。<code>subscription.get</code>（<code>tenancy.subscription.read</code>，租户侧）给租户看自己的套餐、期限与用量（「我的订阅」页）。</p><h2 id="平台扫租户库" tabindex="-1">平台扫租户库 <a class="header-anchor" href="#平台扫租户库" aria-label="Permalink to “平台扫租户库”">​</a></h2><p>日志写入与清理、独立库的初始化与升级这类后台工作，在自建作用域里经框架 <code>TenantShardScope.BindTenantAsync</code> 按租户目录绑定分片，再开工作单元；不在同一个上下文里切换租户。要以某个租户的身份发起一次完整调用（种子、后台写入）用 <code>Contracts</code> 的 <code>ITenantScopeRunner</code>。</p><h2 id="演示租户" tabindex="-1">演示租户 <a class="header-anchor" href="#演示租户" aria-label="Permalink to “演示租户”">​</a></h2><p><code>BasicApp:Seed:EnableDemoData</code> 打开时：</p><ul><li>种子 <code>tenancy.demo</code> 写演示租户 <code>demo</code>（绑定企业版）、其管理员 <code>admin</code>、平台超级管理员在 <code>demo</code> 的成员身份（演示切换租户与模仿），以及流程演示要用的成员账号 <code>manager</code>、<code>lead</code>、<code>hr</code>（密码同管理员，初始密码见 <code>DemoTenantSeeder</code>；系统参数 <code>identity.password</code> 打开时首次登录都须改密）。</li><li>种子 <code>access.demo</code> 在 <code>demo</code> 里建角色 <code>employee</code>（只看本人数据，工作流的查看与发起、聊天的查看与发送，指派给三个成员）与 <code>hr_specialist</code>（自定义数据范围研发部与市场部，指派给 <code>hr</code>），可选模块的权限码只授出已登记的。</li><li>种子 <code>access.demo-policies</code> 在 <code>demo</code> 里写两条只记录的访问策略（<code>demo.off-hours</code>、<code>demo.overseas</code>，内容取同名模板），让命中记录页有数据。</li><li>种子 <code>settings.demo</code> 写两个平台字典（<code>demo_customer_level</code> 带缺省项与停用项，<code>demo_region</code> 是树形）；<code>notification.demo</code> 写三条草稿通知（平台的上手指南，<code>demo</code> 里一条按部门、一条按角色定向），发布之后才展开收件人。</li></ul><p>组织与流程的演示数据见<a href="./organization#演示数据">组织架构</a>与<a href="./workflow#演示流程">工作流</a>。这几个种子都只首写：写过一次（含已删除的）就不再碰。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./organization">组织架构</a> · <a href="./permission">权限管理</a> · <a href="./data-model">数据模型</a></li></ul>`,39)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};